SELECT * FROM (SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Received' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='IN' UNION ALL SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Dispatched' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='OUT') UNION ALL SELECT event_id, NULL case_id, activity, occurred_at timestamp FROM transaction_record_activity) e JOIN (SELECT 'TX:' || transaction_id event_id, transaction_id case_id FROM transaction_record UNION ALL SELECT event_id,case_id FROM lifecycle_case_link WHERE case_table='transaction_record') m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id) WHERE activity IN ('Receiving Requested','Goods Received','Goods Put Away') ORDER BY case_id,timestamp,event_id;
